/*
 * A041397  Denominators of continued fraction convergents to sqrt(213).
 * https://oeis.org/A041397
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = denominator of the n‑th convergent of the simple
 *            continued * fraction for √213. The sequence is generated by the
 *            standard * recurrence for continued fractions of square roots
 * Range:     u8 n <= 5, u16 n <= 11, u32 n <= 22, u64 n <= 41, u128 n <= 83,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    /* static state for lazy memoisation */
    static idx_t computed = 0;              /* largest index computed so far */
    static seq_t *denoms = NULL;            /* array of denominators */
    static size_t cap = 0;                  /* capacity of the array */

    /* constants for √213 */
    static const uint64_t D = 213;          /* the radicand */
    static const uint64_t a0 = 14;          /* floor(√213) */

    /* continued–fraction state variables (valid up to 'computed') */
    static uint64_t m = 0;                  /* m_k value in the algorithm */
    static uint64_t d = 1;                  /* d_k value in the algorithm */
    static uint64_t a_coeff = a0;           /* a_{k-1} value (starts with a0) */

    /* allocate/combine capacities as needed */
    if (denoms == NULL) {
        cap = 16;
        denoms = (seq_t *)malloc(cap * sizeof(seq_t));
        if (denoms == NULL) return 0;       /* out of memory – unlikely in tests */
        denoms[0] = (seq_t)1;               /* a(0) */
    }
    if ((size_t)n >= cap) {
        size_t newcap = (size_t)n + 16;
        seq_t *newptr = (seq_t *)realloc(denoms, newcap * sizeof(seq_t));
        if (newptr == NULL) return 0;       /* out of memory */
        denoms = newptr;
        cap = newcap;
    }

    /* if the requested index is already known */
    if (n <= computed) return denoms[n];

    /* bookkeeping for the recurrence */
    seq_t prev_q, prev_prev_q;
    if (computed == 0) {
        prev_q = denoms[0];      /* q[0] = 1 */
        prev_prev_q = (seq_t)0;  /* q[-1] = 0 */
    } else {
        prev_q = denoms[computed];          /* q[computed] */
        prev_prev_q = denoms[computed - 1];  /* q[computed-1] */
    }

    /* compute terms from computed+1 up to n */
    for (idx_t k = computed + 1; k <= n; ++k) {
        /* generate next coefficient a_k */
        m = d * a_coeff - m;
        d = (D - (uint64_t)(m * m)) / d;      /* integer division; exact */
        uint64_t ak = (a0 + m) / d;           /* next continued–fraction term */
        a_coeff = ak;                         /* store for next iteration */

        /* recurrence for denominators: q_k = a_k * q_{k-1} + q_{k-2} */
        seq_t qk = (seq_t)ak * prev_q + prev_prev_q;
        denoms[k] = qk;

        /* shift for the next step */
        prev_prev_q = prev_q;
        prev_q = qk;
    }

    computed = n;
    return denoms[n];
}
